import csv
import io


def parse_csv(raw_csv: str):
    width = 3
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
        )
    )

    def fit_width(record):
        if len(record) > width:
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    # The title and any leading blank records have at most one filled cell.
    header_index = 0
    while header_index < len(records):
        record = records[header_index]
        if sum(bool(value.strip()) for value in record) > 1:
            break
        header_index += 1

    if not records:
        return {"columns": [], "rows": []}

    if header_index == len(records):
        header_index = next(
            (i for i, record in enumerate(records) if any(v.strip() for v in record)),
            0,
        )

    return {
        "columns": fit_width(records[header_index]),
        "rows": [fit_width(record) for record in records[header_index + 1:]],
    }
